140	                          llvm::ArrayRef<DriverDef> drivers) {
141	  Flavor f = parseFlavor(argsV);
142	  auto it =
143	      llvm::find_if(drivers, [=](auto &driverdef) { return driverdef.f == f; });
144	  if (it == drivers.end()) {
